# SPDX-License-Identifier: AGPL-3.0-only
def solve(payload):
    best = {0: (0, ())}
    for item in sorted(payload['items'], key=lambda entry: entry['id']):
        for used in range(payload['capacity'] + 1):
            if used not in best:
                continue
            value, ids = best[used]
            weight = used + item['weight']
            if weight <= payload['capacity']:
                candidate = (value + item['value'], ids + (item['id'],))
                key = lambda entry: (-entry[0], len(entry[1]), entry[1])
                if weight not in best or key(candidate) < key(best[weight]):
                    best[weight] = candidate
    weight, (value, ids) = min(best.items(), key=lambda pair: (-pair[1][0], pair[0], len(pair[1][1]), pair[1][1]))
    return {'value': value, 'weight': weight, 'items': list(ids)}

